/** Atomic real job/context/manifest registration; no lease, invocation, send or success is fabricated. */
public final class FormalVerificationJobs {
 private final JdbcTemplate db;private final PermissionSchema json;private final FormalInvocationSchema schema;private final RunTokenAuthoritySchema runtime;
 public FormalVerificationJobs(DataSource data,PermissionSchema json,FormalInvocationSchema schema,RunTokenAuthoritySchema runtime){this.db=new JdbcTemplate(data);db.setQueryTimeout(5);this.json=json;this.schema=schema;this.runtime=runtime;}
 record Job(String tenant,String project,String verification,String operation,String actor,String key,String run,String principal,String step,String action,String context,String scope,String rules,String tokenizer,String model,String request,String requestHash,String inputHash,String dependencies,String dependenciesHash,String manifest,LocalDateTime created,String classification){}
 Job create(EnterpriseAccess.Admission a,FormalVerificationPreparation.Prepared prepared)throws Exception{
  current(a);prepared.requireCurrent(a);var existing=read(a.context().tenant_id(),prepared.verificationId());if(existing.isPresent()){if(!existing.get().requestHash().equals(prepared.requestHash())||!existing.get().actor().equals(a.actorId())||!existing.get().key().equals(prepared.key()))throw new TenantAccessException(ErrorCode.IDEMPOTENCY_CONFLICT);return existing.get();}
  String tenant=a.context().tenant_id(),project=prepared.projectId(),actor=a.actorId();if(!tenant.equals(prepared.tenantId())||!actor.equals(prepared.actorId())||project==null)bad();
  String run=id(),principal=id(),step=id(),action=id(),context=id(),scopeId=id(),rulesId=id(),tokenizerId=id(),accessId=id();var now=one(db.query("SELECT UTC_TIMESTAMP(6)",(r,n)->r.getTimestamp(1).toLocalDateTime()));String classification=prepared.input().classification();
  var scope=json.object().put("schema_version","1.0.0").put("tenant_id",tenant).put("project_id",project).put("initiator_id",actor).put("run_id",run).put("execution_kind","SYSTEM_JOB");var resources=scope.putArray("resources");prepared.permissions().stream().map(RunTokenAuthoritySchema.Permission::scope).distinct().forEach(s->resources.add(json.tree(s)));runtime.scopeManifest(json.canonical(scope),tenant,project,actor,run,"SYSTEM_JOB");
  var capabilities=json.object().put("schema_version","1.0.0").put("tenant_id",tenant).put("project_id",project).put("initiator_id",actor).put("run_id",run).put("principal_id",principal).put("scope_sha256",schema.hash(scope));capabilities.putArray("services").add(json.object().put("service_uri",prepared.serviceUri()).put("audience",prepared.audience()));capabilities.set("permissions",json.tree(prepared.permissions()));runtime.principalManifest(json.canonical(capabilities),tenant,project,actor,run,principal,scope);
  var request=prepared.request();String roleId=text(request.required("role_basis"),"version_id"),promptId=text(request.required("prompt_basis"),"version_id");
  var tokenized=json.object().put("schema_version","1.0.0").put("tokenizer_version",prepared.tokenization().tokenizerVersion()).put("executable_sha256",prepared.tokenization().executableSha256()).put("input_sha256",prepared.tokenization().inputSha256()).put("output_sha256",prepared.tokenization().outputSha256()).put("token_count",prepared.tokenization().tokenCount().toString());
  var sources=sourceAuthorizations(prepared.input().registered().sources());
  var contextDocument=json.object().put("schema_version","1.0.0").put("tenant_id",tenant).put("project_id",project).put("context_manifest_id",context).put("prompt_revision",promptId).put("tokenizer_revision",prepared.tokenization().tokenizerVersion()).put("token_count",prepared.tokenization().tokenCount().toString()).put("dependency_access_set_id",accessId);contextDocument.set("exact_input_ref",request.required("exact_input"));contextDocument.set("source_manifest",sources);
  var deps=json.object().put("schema_version","1.0.0");deps.set("role",prepared.role());deps.set("prompt",prepared.prompt());deps.set("rules",prepared.rules());deps.set("model",prepared.model());deps.set("price",prepared.price().canonicalDocument());deps.set("tokenization",tokenized);deps.set("source_authorizations",sources);deps.set("scope",scope);deps.set("principal",capabilities);deps.set("context",contextDocument);deps.put("input_authorization_sha256",prepared.input().authorizationSha256()).put("price_authorization_sha256",prepared.price().sourceAuthorizationSha256());
  String requestJson=schema.canonical(request),depsJson=schema.canonical(deps),inputHash=prepared.input().inputSha256();
  Job job=new Job(tenant,project,prepared.verificationId(),prepared.operationId(),actor,prepared.key(),run,principal,step,action,context,scopeId,rulesId,tokenizerId,prepared.model().required("model_config_revision").textValue(),requestJson,prepared.requestHash(),inputHash,depsJson,schema.hash(deps),schema.manifestSha256(),now,classification);
  manifest(job,scopeId,"SCOPE",scope);manifest(job,rulesId,"RULES",prepared.rules());manifest(job,tokenizerId,"TOKENIZATION",tokenized);
  version(tenant,project,accessId,"DEPENDENCY_ACCESS_SET",schema.hash(sources));insert("dependency_access_set",Map.of("tenant_id",tenant,"project_id",project,"access_set_id",accessId,"manifest_sha256",schema.hash(sources),"content_sha256",schema.hash(sources),"created_by",actor,"created_at",now,"classification",classification));
  for(var e:prepared.input().registered().sources().entrySet())insert("dependency_access_member",Map.of("tenant_id",tenant,"access_set_id",accessId,"upstream_version_id",e.getKey(),"rights_revision",e.getValue().rights().rightsRevision(),"created_by",actor,"created_at",now,"classification",classification));
  version(tenant,project,context,"CONTEXT_MANIFEST",schema.hash(contextDocument));var c=metadata(job,schema.manifestSha256());c.put("project_id",project);c.put("context_manifest_id",context);c.put("exact_input_ref",json.canonical(request.required("exact_input")));c.put("source_manifest",json.canonical(sources));c.put("prompt_revision",promptId);c.put("tokenizer_revision",prepared.tokenization().tokenizerVersion());c.put("token_count",prepared.tokenization().tokenCount());c.put("dependency_access_set_id",accessId);c.put("content_sha256",schema.hash(contextDocument));insert("context_manifest",c);
  var execution=metadata(job,runtime.manifestSha256());execution.put("run_id",run);execution.put("project_id",project);execution.put("execution_kind","SYSTEM_JOB");execution.put("scope_manifest",json.canonical(scope));insert("execution_registry",execution);
  var p=metadata(job,runtime.manifestSha256());p.put("principal_id",principal);p.put("project_id",project);p.put("initiator_id",actor);p.put("run_id",run);p.put("capability_manifest",json.canonical(capabilities));p.put("status","ACTIVE");p.put("revision",1);p.put("updated_at",now);insert("run_principal",p);
  var j=metadata(job,runtime.manifestSha256());j.put("run_id",run);j.put("execution_kind","SYSTEM_JOB");j.put("project_id",project);j.put("job_type","MODEL_VERIFICATION");j.put("initiator_id",actor);j.put("input_manifest",requestJson);j.put("config_revision",job.model());j.put("budget_revision",text(request.required("enterprise_budget_basis"),"version_id"));j.put("parent_budget_id",one(db.query("SELECT budget_id FROM budget_revision WHERE tenant_id=? AND budget_revision=? LIMIT 2",(r,n)->r.getString(1),tenant,text(request.required("parent_budget_basis"),"version_id"))));j.put("target_kind","CONFIGURATION");j.put("target_id",text(prepared.model(),"config_id"));j.put("target_revision",job.model());j.put("input_sha256",inputHash);j.put("scope_manifest_id",scopeId);j.put("rule_manifest_id",rulesId);j.put("status","RUNNING");j.put("workflow_id",null);j.put("started_at",now);j.put("revision",1);j.put("updated_at",now);insert("system_job_run",j);
  var s=metadata(job,runtime.manifestSha256());s.put("project_id",project);s.put("run_id",run);s.put("step_id",step);s.put("role_version",roleId);s.put("input_sha256",inputHash);s.put("status","READY");s.put("lease_generation",0);s.put("revision",1);s.put("updated_at",now);insert("run_step",s);
  var ac=metadata(job,runtime.manifestSha256());ac.put("project_id",project);ac.put("run_id",run);ac.put("step_id",step);ac.put("action_id",action);ac.put("input_sha256",inputHash);ac.put("origin_run_id",run);ac.put("origin_step_id",step);ac.put("origin_action_id",action);ac.put("kind","MODEL_CALL");ac.put("arguments_sha256",job.requestHash());ac.put("tool_version",job.model());ac.put("state","BOUND");ac.put("operation_id",job.operation());ac.put("lease_generation",0);ac.put("revision",1);ac.put("updated_at",now);insert("step_action_binding",ac);
  var side=metadata(job,schema.manifestSha256());side.put("project_id",project);side.put("verification_id",job.verification());side.put("operation_id",job.operation());side.put("run_id",run);side.put("principal_id",principal);side.put("step_id",step);side.put("action_id",action);side.put("context_manifest_id",context);side.put("scope_manifest_id",scopeId);side.put("rule_manifest_id",rulesId);side.put("tokenization_manifest_id",tokenizerId);side.put("model_config_revision",job.model());side.put("execution_mode","ADAPTER_MTLS");side.put("job_type","MODEL_VERIFICATION");side.put("idempotency_key",job.key());side.put("canonical_request",job.request());side.put("request_body_sha256",job.requestHash());side.put("input_sha256",inputHash);side.put("dependency_snapshot",job.dependencies());side.put("dependency_sha256",job.dependenciesHash());insert("formal_model_verification_job",side);
  var event=evidence(job);var audit=metadata(job,schema.manifestSha256());audit.put("project_id",project);audit.put("audit_id",id());audit.put("subject_id",actor);audit.put("action","model.verification_job_started");audit.put("resource_ref",schema.canonical(event));audit.put("result","SUCCESS");audit.put("request_id",job.verification());audit.put("trace_id",job.verification());insert("audit_event",audit);insert("outbox_event",Map.of("tenant_id",tenant,"event_id",id(),"aggregate_id",run,"aggregate_revision",1,"event_type","model.verification_job_started","payload",schema.canonical(event),"occurred_at",now));
  prepared.requireCurrent(a);var actual=read(tenant,job.verification()).orElseThrow(()->new TenantAccessException(ErrorCode.CONTENT_MISMATCH));if(!job.equals(actual))bad();return actual;
 }
 Job byRun(String tenant,String run)throws Exception{var ids=db.query("SELECT verification_id FROM formal_model_verification_job WHERE tenant_id=? AND run_id=? LIMIT 2",(r,n)->r.getString(1),tenant,run);return read(tenant,one(ids)).orElseThrow(()->new TenantAccessException(ErrorCode.CONTENT_MISMATCH));}
 Optional<Job> read(String tenant,String verification)throws Exception{
  if(!TenantScope.requireCurrent().tenantId().equals(tenant))bad();var rows=db.query("SELECT * FROM formal_model_verification_job WHERE tenant_id=? AND verification_id=? LIMIT 2",(r,n)->new Job(r.getString("tenant_id"),r.getString("project_id"),r.getString("verification_id"),r.getString("operation_id"),r.getString("created_by"),r.getString("idempotency_key"),r.getString("run_id"),r.getString("principal_id"),r.getString("step_id"),r.getString("action_id"),r.getString("context_manifest_id"),r.getString("scope_manifest_id"),r.getString("rule_manifest_id"),r.getString("tokenization_manifest_id"),r.getString("model_config_revision"),r.getString("canonical_request"),r.getString("request_body_sha256"),r.getString("input_sha256"),r.getString("dependency_snapshot"),r.getString("dependency_sha256"),r.getString("schema_manifest_sha256"),r.getTimestamp("created_at").toLocalDateTime(),r.getString("classification")),tenant,verification);if(rows.size()>1)bad();if(rows.isEmpty()){if(!db.query("SELECT audit_id FROM audit_event WHERE tenant_id=? AND action='model.verification_job_started' AND request_id=? LIMIT 1",(r,n)->r.getString(1),tenant,verification).isEmpty())bad();return Optional.empty();}Job j=rows.get(0);verify(j);return Optional.of(j);
 }
 private void verify(Job j)throws Exception{
  var request=schema.read("VerificationRequest",j.request().getBytes(java.nio.charset.StandardCharsets.UTF_8),1048576);var deps=schema.parse(j.dependencies());if(!j.requestHash().equals(schema.hash(request))||!j.dependenciesHash().equals(schema.hash(deps))||!schema.canonical(request).equals(j.request())||!schema.canonical(deps).equals(j.dependencies())||!j.manifest().equals(schema.manifestSha256())||!j.inputHash().equals(text(request.required("exact_input"),"sha256"))||!j.model().equals(text(request,"model_config_revision"))||!j.project().equals(text(request,"project_id")))bad();
  runtime.scopeManifest(json.canonical(deps.required("scope")),j.tenant(),j.project(),j.actor(),j.run(),"SYSTEM_JOB");runtime.principalManifest(json.canonical(deps.required("principal")),j.tenant(),j.project(),j.actor(),j.run(),j.principal(),deps.required("scope"));
  // Every original registered row is loaded independently; a missing inner-join counterpart cannot become an empty result.
  equalJson(j,"execution_registry","scope_manifest","run_id",j.run(),deps.required("scope"));equalJson(j,"run_principal","capability_manifest","principal_id",j.principal(),deps.required("principal"));equalJson(j,"system_job_run","input_manifest","run_id",j.run(),request);
  var links=one(db.query("SELECT COUNT(*) FROM system_job_run WHERE tenant_id=? AND project_id=? AND run_id=? AND initiator_id=? AND execution_kind='SYSTEM_JOB' AND job_type='MODEL_VERIFICATION' AND target_kind='CONFIGURATION' AND target_id=? AND target_revision=? AND config_revision=? AND input_sha256=? AND scope_manifest_id=? AND rule_manifest_id=? AND workflow_id IS NULL AND schema_version='1.0.0' AND schema_manifest_sha256=?",(r,n)->r.getInt(1),j.tenant(),j.project(),j.run(),j.actor(),text(deps.required("model"),"config_id"),j.model(),j.model(),j.inputHash(),j.scope(),j.rules(),runtime.manifestSha256()));if(links!=1)bad();
  if(one(db.query("SELECT COUNT(*) FROM run_step WHERE tenant_id=? AND project_id=? AND run_id=? AND step_id=? AND role_version=? AND input_sha256=?",(r,n)->r.getInt(1),j.tenant(),j.project(),j.run(),j.step(),text(request.required("role_basis"),"version_id"),j.inputHash()))!=1)bad();
  if(one(db.query("SELECT COUNT(*) FROM step_action_binding WHERE tenant_id=? AND project_id=? AND run_id=? AND step_id=? AND action_id=? AND input_sha256=? AND arguments_sha256=? AND tool_version=? AND operation_id=? AND origin_run_id=run_id AND origin_step_id=step_id AND origin_action_id=action_id AND kind='MODEL_CALL'",(r,n)->r.getInt(1),j.tenant(),j.project(),j.run(),j.step(),j.action(),j.inputHash(),j.requestHash(),j.model(),j.operation()))!=1)bad();
  for(var entry:Map.of(j.scope(),"scope",j.rules(),"rules",j.tokenizer(),"tokenization").entrySet()){var document=one(db.query("SELECT canonical_document FROM formal_model_manifest WHERE tenant_id=? AND project_id=? AND manifest_id=? AND content_sha256=? AND schema_version='1.0.0' AND schema_manifest_sha256=? AND created_by=? LIMIT 2",(r,n)->r.getString(1),j.tenant(),j.project(),entry.getKey(),schema.hash(deps.required(entry.getValue())),schema.manifestSha256(),j.actor()));if(!schema.canonical(deps.required(entry.getValue())).equals(document))bad();}
  equalJson(j,"context_manifest","exact_input_ref","context_manifest_id",j.context(),request.required("exact_input"));equalJson(j,"context_manifest","source_manifest","context_manifest_id",j.context(),deps.required("source_authorizations"));
  var context=deps.required("context");String accessId=text(context,"dependency_access_set_id");
  if(!j.context().equals(text(context,"context_manifest_id"))||!j.project().equals(text(context,"project_id"))||!j.tenant().equals(text(context,"tenant_id")))bad();
  if(one(db.query("SELECT COUNT(*) FROM context_manifest WHERE tenant_id=? AND project_id=? AND context_manifest_id=? AND prompt_revision=? AND tokenizer_revision=? AND token_count=? AND dependency_access_set_id=? AND content_sha256=? AND schema_version='1.0.0' AND schema_manifest_sha256=? AND created_by=? AND created_at=? AND classification=?",(r,n)->r.getInt(1),j.tenant(),j.project(),j.context(),text(context,"prompt_revision"),text(context,"tokenizer_revision"),text(context,"token_count"),accessId,schema.hash(context),schema.manifestSha256(),j.actor(),j.created(),j.classification()))!=1)bad();
  if(one(db.query("SELECT COUNT(*) FROM dependency_access_set WHERE tenant_id=? AND project_id=? AND access_set_id=? AND manifest_sha256=? AND content_sha256=? AND created_by=? AND created_at=? AND classification=?",(r,n)->r.getInt(1),j.tenant(),j.project(),accessId,schema.hash(deps.required("source_authorizations")),schema.hash(deps.required("source_authorizations")),j.actor(),j.created(),j.classification()))!=1)bad();
  var sourceRows=db.query("SELECT upstream_version_id,rights_revision FROM dependency_access_member WHERE tenant_id=? AND access_set_id=? ORDER BY upstream_version_id LIMIT 4097",(r,n)->Map.entry(r.getString(1),r.getString(2)),j.tenant(),accessId);var expectedSources=FormalInvocationSourceManifest.rights(deps.required("source_authorizations"));if(sourceRows.size()>4096||!sourceRows.equals(new ArrayList<>(expectedSources.entrySet())))bad();
  versionMatches(j,j.scope(),"FORMAL_MODEL_MANIFEST",schema.hash(deps.required("scope")));versionMatches(j,j.rules(),"FORMAL_MODEL_MANIFEST",schema.hash(deps.required("rules")));versionMatches(j,j.tokenizer(),"FORMAL_MODEL_MANIFEST",schema.hash(deps.required("tokenization")));versionMatches(j,j.context(),"CONTEXT_MANIFEST",schema.hash(context));versionMatches(j,accessId,"DEPENDENCY_ACCESS_SET",schema.hash(deps.required("source_authorizations")));
  if(one(db.query("SELECT COUNT(*) FROM formal_model_verification_job WHERE tenant_id=? AND verification_id=? AND execution_mode='ADAPTER_MTLS' AND job_type='MODEL_VERIFICATION' AND schema_version='1.0.0'",(r,n)->r.getInt(1),j.tenant(),j.verification()))!=1)bad();
  var event=evidence(j);var audit=one(db.query("SELECT resource_ref FROM audit_event WHERE tenant_id=? AND project_id=? AND subject_id=? AND created_by=? AND action='model.verification_job_started' AND result='SUCCESS' AND reason_code IS NULL AND request_id=? AND trace_id=? AND schema_version='1.0.0' AND schema_manifest_sha256=? AND classification=? LIMIT 2",(r,n)->r.getString(1),j.tenant(),j.project(),j.actor(),j.actor(),j.verification(),j.verification(),schema.manifestSha256(),j.classification()));var emitted=one(db.query("SELECT payload FROM outbox_event WHERE tenant_id=? AND aggregate_id=? AND aggregate_revision=1 AND event_type='model.verification_job_started' LIMIT 2",(r,n)->r.getString(1),j.tenant(),j.run()));if(!schema.canonical(event).equals(schema.canonical(schema.parse(audit)))||!schema.canonical(event).equals(schema.canonical(schema.parse(emitted))))bad();
 }
 private void versionMatches(Job j,String id,String kind,String hash){if(one(db.query("SELECT COUNT(*) FROM version_registry WHERE tenant_id=? AND owner_project_id=? AND version_id=? AND entity_kind=? AND content_sha256=?",(r,n)->r.getInt(1),j.tenant(),j.project(),id,kind,hash))!=1)bad();}
 static JsonNode sourceAuthorizations(Map<String,SourceReadProtocol.VerifiedSource> supplied){
  var sources=com.fasterxml.jackson.databind.node.JsonNodeFactory.instance.objectNode();
  supplied.entrySet().stream().sorted(Map.Entry.comparingByKey()).forEach(e->sources.set(e.getKey(),AgentPublicationWitness.tree(e.getValue())));
  return sources;
 }
 JsonNode evidence(Job j){return AgentPublicationWitness.tree(Map.of("schema_version","1.0.0","kind","MODEL_VERIFICATION_JOB_STARTED","job",j));}
 private void equalJson(Job j,String table,String field,String idField,String id,JsonNode expected)throws Exception{var value=one(db.query("SELECT "+field+" FROM "+table+" WHERE tenant_id=? AND "+idField+"=? LIMIT 2",(r,n)->r.getString(1),j.tenant(),id));if(!schema.canonical(expected).equals(schema.canonical(schema.parse(value))))bad();}
 private void manifest(Job j,String id,String kind,JsonNode value)throws Exception{String hash=schema.hash(value);version(j.tenant(),j.project(),id,"FORMAL_MODEL_MANIFEST",hash);var m=metadata(j,schema.manifestSha256());m.put("project_id",j.project());m.put("manifest_id",id);m.put("manifest_kind",kind);m.put("canonical_document",schema.canonical(value));m.put("content_sha256",hash);insert("formal_model_manifest",m);}
 private void version(String tenant,String project,String id,String kind,String hash){insert("version_registry",Map.of("tenant_id",tenant,"version_id",id,"owner_project_id",project,"entity_kind",kind,"content_sha256",hash));}
 private Map<String,Object> metadata(Job j,String manifest){var m=new LinkedHashMap<String,Object>();m.put("tenant_id",j.tenant());m.put("schema_version","1.0.0");m.put("schema_manifest_sha256",manifest);m.put("created_by",j.actor());m.put("created_at",j.created());m.put("classification",j.classification());return m;}
 private void insert(String table,Map<String,Object> values){var keys=new ArrayList<>(values.keySet());if(db.update("INSERT INTO "+table+" ("+String.join(",",keys)+") VALUES ("+String.join(",",Collections.nCopies(keys.size(),"?"))+")",keys.stream().map(values::get).toArray())!=1)bad();}
 private static void current(EnterpriseAccess.Admission a){if(!TransactionSynchronizationManager.isActualTransactionActive()||!TenantScope.requireCurrent().tenantId().equals(a.context().tenant_id())||!TenantScope.requireCurrent().subjectId().equals(a.actorId()))throw new TenantAccessException(ErrorCode.ACCESS_DENIED);}
 private static String id(){return UUID.randomUUID().toString();}private static String text(JsonNode n,String k){var v=n.required(k);if(!v.isTextual())bad();return v.textValue();}private static <T>T one(List<T> r){if(r.size()!=1||r.get(0)==null)bad();return r.get(0);}private static void bad(){throw new TenantAccessException(ErrorCode.CONTENT_MISMATCH);}
}
